/* Two rows no face takes together, and the reason, spelled for each
   face that can be given both: the CLI (both flags), a scene (both
   keys), the object (both members set). NULL: that face cannot
   carry one of the two, so it has nothing to refuse. */
typedef struct
{
  int         a, b; /* WFM_SURFACE_<owner>_<name> */
  const char *cli_why;
  const char *json_why;
  const char *obj_why;
} wfm_surface_exclusive_t;

#define WFM_SURFACE_N_EXCLUSIVE 1
static const wfm_surface_exclusive_t
    WFM_SURFACE_EXCLUSIVE[1] = {
  {
    .a = WFM_SURFACE_source_data,
    .b = WFM_SURFACE_source_data_from_file,
    .cli_why = "--data and --data-from-file cannot both be given: a "
        "payload has one data source",
    .json_why = "\"data\" and \"data_from_file\" cannot both be given: a "
        "payload has one data source",
    .obj_why = "a source's data and data_from_file cannot both be set:"
        " a payload has one data source",
  },
};

/* Whether a row's member holds a value: the object face's
   "given". Only the kinds an exclusion may name (the generator
   refuses any other) have an unset value to test for. */
static inline int
wfm_surface_row_is_set (const wfm_surface_row_t *r,
                        const void              *base)
{
  const char *m = (const char *)base + r->off;
  switch (r->kind)
    {
    case WFM_SV_FIELD:
      return ((const wfm_seq_t *)m)->len != 0;
    case WFM_SV_BESPOKE:
      return *(const void *const *)m != NULL;
    case WFM_SV_SYMBOLS:
      return *(const size_t *)((const char *)base + r->len_off)
             != 0;
    default:
      return 0;
    }
}

/* A Field row with no repetition count refuses *REPS: only the
   rows with `field_reps` repeat (a preamble). One reason per face.
*/
#define WFM_SURFACE_REPS_WHY_CLI \
  "only --acq-code repeats (a preamble): drop the *REPS"
#define WFM_SURFACE_REPS_WHY_JSON \
  "only \"acq_code\" repeats (a preamble): drop the *REPS"

/* --help option lines, one string per USAGE section. */
#define WFM_SURFACE_HELP_SIGNAL \
  "  --fs HZ         Sample rate in Hz, one per segment and shared by all its\n" \
  "                  sources. (default 1.0)\n" \
  "  --count N[:N]   Segment on-time in samples, before the trailing gap: 0\n" \
  "                  derives it from the sources, or 1024 when they set none.\n" \
  "                  (default 0)\n" \
  "  --off N[:N]     Trailing gap after the on-time, in samples. (default 0)\n" \
  "  --repeats N     Play the segment this many times back-to-back (each instance\n" \
  "                  = delay + on-time + trailing gap) before advancing.\n" \
  "                  (default 1)\n" \
  "  --delay N[:N]   Leading gap before the on-time, in samples: the burst arrives\n" \
  "                  after this delay, and the gap carries the noise floor like\n" \
  "                  off_samples. (default 0)\n" \
  "  --gap-noise M   Gap policy for this segment's delay and trailing gap. One of:\n" \
  "                  auto | off. (default auto)\n" \
  "  --freq HZ[:HZ]  Carrier or offset frequency in Hz; for chirp, the sweep\n" \
  "                  start. (default 0.0)\n" \
  "  --seed N        PRNG and LFSR seed for the noise and PN streams. (default 0)\n" \
  "  --sps N         Samples per symbol (PSK) or per chip (PN): the oversampling\n" \
  "                  factor. (default 1)\n" \
  "  --f-end HZ[:HZ] Chirp end frequency in Hz; ignored by other types.\n" \
  "                  (default 0.0)\n"

#define WFM_SURFACE_HELP_TYPE \
  "  --type TYPE     Waveform type. One of: tone | noise | pn | bpsk | qpsk |\n" \
  "                  chirp | bits | symbols | dsss. (default tone)\n"

#define WFM_SURFACE_HELP_NOISE \
  "  --snr DB[:DB]   Signal-to-noise ratio in dB, interpreted per snr_mode.\n" \
  "                  (default 100.0)\n" \
  "  --snr-mode MODE How snr is interpreted. One of: auto | fs | ebno | esno.\n" \
  "                  (default auto)\n"

#define WFM_SURFACE_HELP_PN \
  "  --pn-length N   PN LFSR register length in bits, 2 to 64 for the PN-bearing\n" \
  "                  types; the sequence period is 2^pn_length - 1. (default 15)\n" \
  "  --pn-poly N     PN generator polynomial, in the Galois bit-vector convention;\n" \
  "                  0 selects a maximal-length (MLS) polynomial for pn_length.\n" \
  "                  (default 0)\n" \
  "  --lfsr TYPE     PN LFSR realisation. One of: galois | fibonacci.\n" \
  "                  (default galois)\n"

#define WFM_SURFACE_HELP_AMPLITUDE \
  "  --level DB[:DB] Source power in dBFS (<= 0; 0 is unit power). (default 0.0)\n"

#define WFM_SURFACE_HELP_DOPPLER \
  "  --doppler PPM[:PPM]\n" \
  "                  Clock Doppler in ppm: the received time base is rescaled by 1\n" \
  "                  + doppler*1e-6, so the symbol and chip rates move with the\n" \
  "                  carrier and a timing loop sees the error a carrier-only\n" \
  "                  `freq` offset hides. (default 0.0)\n" \
  "  --doppler-rate PPM_S[:PPM_S]\n" \
  "                  Linear ramp on `doppler`, in ppm per second of elapsed stream\n" \
  "                  time. (default 0.0)\n" \
  "  --carrier-hz HZ RF carrier in Hz that the ppm figures are referred to.\n" \
  "                  (default 0.0)\n" \
  "  --doppler-lifetime L\n" \
  "                  How long this source's Doppler channel lives. One of:\n" \
  "                  per_instance | persist. (default per_instance)\n"

#define WFM_SURFACE_HELP_BITS \
  "  --modulation M  Symbol mapping of a bits pattern. One of: none | bpsk | qpsk.\n" \
  "                  (default bpsk)\n" \
  "  --data-from-file PATH\n" \
  "                  A data source read from a file of packed octets, MSB first,\n" \
  "                  or `-` for stdin, instead of data. Not with --data.\n" \
  "  --data FIELD    A frame's payload drawn from a data source: a Field on the\n" \
  "                  command line and in a scene, a bit array in Python. Not with\n" \
  "                  --data-from-file.\n" \
  "  --data-len BITS Bits of the data source per frame: the data:LEN of the common\n" \
  "                  frame [preamble x reps | sync | data:LEN | crc]. (default 0)\n" \
  "  --fill FIELD    The bits that pad a data source's last frame when it does not\n" \
  "                  divide into data_len-bit frames, tiled from their first bit;\n" \
  "                  stdin on a framed source always needs them.\n"

#define WFM_SURFACE_HELP_PULSE \
  "  --pulse SHAPE   Pulse shape per symbol or chip, for\n" \
  "                  pn/bpsk/qpsk/bits/symbols/dsss. One of: rect | rrc.\n" \
  "                  (default rect)\n" \
  "  --rrc-beta R    RRC roll-off factor, in (0, 1], when pulse=rrc.\n" \
  "                  (default 0.35)\n" \
  "  --rrc-span N    RRC filter support in symbols when pulse=rrc, ONE-SIDED: the\n" \
  "                  filter has 2*rrc_span*sps + 1 taps, unit energy (sum of h^2 =\n" \
  "                  1). (default 8)\n"

#define WFM_SURFACE_HELP_SYMBOLS \
  "  --symbols-file F\n" \
  "                  For type=symbols: a complex constellation stream.\n"

#define WFM_SURFACE_HELP_DSSS_BURST \
  "  --acq-code FIELD\n" \
  "                  The preamble code, sent acq_reps times at the head of the\n" \
  "                  frame (a Field's *REPS on the command line and in a scene) --\n" \
  "                  the coherent pull-in target BurstDespreader.set_acq and\n" \
  "                  BurstDemod.set_preamble lock to.\n" \
  "  --data-code FIELD\n" \
  "                  For type=dsss: the payload spreading code, a second code\n" \
  "                  distinct from acq_code.\n"

#define WFM_SURFACE_HELP_DSSS_CONT \
  "  --symbol-rate HZ\n" \
  "                  For type=dsss: > 0 selects CONTINUOUS asynchronous mode.\n" \
  "                  (default 0.0)\n" \
  "  --code-only     Continuous dsss data source: 1 = code-only (the pure\n" \
  "                  spreading code, no data modulation); 0 = data-modulated (the\n" \
  "                  payload when supplied, else the seeded PN). (default 0)\n"

#define WFM_SURFACE_HELP_CODED \
  "  --frame FILE    A frame DESCRIPTION, the whole frame: fields in wire order,\n" \
  "                  and stages that each name the span they cover (crc16, rs,\n" \
  "                  randomise, interleave, conv, or a kind of your own).\n"

/* The keys each object of a scene takes, generated from the schema's
   `properties` (docs/schema/wfmgen.schema.json). The reader refuses any
   other key by name: the schema and the reader are one table (#1153). */
